CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, name TEXT NOT NULL DEFAULT '', pass_hash TEXT, salt TEXT, role TEXT NOT NULL DEFAULT 'staff', perms TEXT NOT NULL DEFAULT '[]', off TEXT NOT NULL DEFAULT '[]', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), last_login TEXT ); CREATE TABLE IF NOT EXISTS sessions ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), expires_at TEXT NOT NULL, last_seen TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), remember INTEGER NOT NULL DEFAULT 0, ip_hash TEXT, ua TEXT ); CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id); CREATE INDEX IF NOT EXISTS idx_sessions_expires ON sessions(expires_at); CREATE TABLE IF NOT EXISTS set_tokens ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'set', expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE INDEX IF NOT EXISTS idx_set_tokens_user ON set_tokens(user_id); CREATE TABLE IF NOT EXISTS leads ( id TEXT PRIMARY KEY, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), form TEXT NOT NULL, pipeline TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'new', name TEXT NOT NULL DEFAULT '', email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', topic TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '', fields TEXT NOT NULL DEFAULT '{}', file_key TEXT, file_name TEXT, page TEXT NOT NULL DEFAULT '', utm TEXT NOT NULL DEFAULT '{}', ip_hash TEXT, spam_score INTEGER NOT NULL DEFAULT 0, email_status TEXT NOT NULL DEFAULT 'pending', email_error TEXT ); CREATE INDEX IF NOT EXISTS idx_leads_created ON leads(created_at); CREATE INDEX IF NOT EXISTS idx_leads_form_stage ON leads(form, stage); CREATE INDEX IF NOT EXISTS idx_leads_pipeline_stage ON leads(pipeline, stage); CREATE INDEX IF NOT EXISTS idx_leads_email ON leads(email); CREATE TABLE IF NOT EXISTS notes ( id TEXT PRIMARY KEY, lead_id TEXT NOT NULL, user_id TEXT NOT NULL, body TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE INDEX IF NOT EXISTS idx_notes_lead ON notes(lead_id); CREATE TABLE IF NOT EXISTS activity ( id TEXT PRIMARY KEY, lead_id TEXT, user_id TEXT, action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE INDEX IF NOT EXISTS idx_activity_lead ON activity(lead_id); CREATE INDEX IF NOT EXISTS idx_activity_created ON activity(created_at); CREATE TABLE IF NOT EXISTS settings ( key TEXT PRIMARY KEY, enc_value TEXT NOT NULL, updated_by TEXT, updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE TABLE IF NOT EXISTS auth_attempts ( id INTEGER PRIMARY KEY AUTOINCREMENT, scope TEXT NOT NULL, key_hash TEXT NOT NULL, at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), ok INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS idx_auth_attempts_key ON auth_attempts(scope, key_hash, at); CREATE TABLE IF NOT EXISTS audit_log ( id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, action TEXT NOT NULL, target TEXT NOT NULL DEFAULT '', detail TEXT NOT NULL DEFAULT '', ip_hash TEXT, at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE INDEX IF NOT EXISTS idx_audit_at ON audit_log(at); CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_log(user_id); CREATE TABLE IF NOT EXISTS media ( key TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL DEFAULT '', size INTEGER NOT NULL DEFAULT 0, uploaded_by TEXT, at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE TABLE IF NOT EXISTS email_log ( id INTEGER PRIMARY KEY AUTOINCREMENT, lead_id TEXT, kind TEXT NOT NULL, to_addr TEXT NOT NULL DEFAULT '', ok INTEGER NOT NULL DEFAULT 0, error TEXT, at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) ); CREATE INDEX IF NOT EXISTS idx_email_log_at ON email_log(at); CREATE TABLE IF NOT EXISTS cache ( key TEXT PRIMARY KEY, value TEXT NOT NULL, expires_at TEXT NOT NULL );
